# analytics.py
"""
Retail Analytics Engine:
- Active People Count & Total Unique Visitors
- Zone Occupancy (Store Zone, Checkout Zone, Shelf Zone)
- Queue Count & Queue Alert Monitoring
- Dwell Time Tracking & Real-Time Average Dwell
"""
import time
from dataclasses import dataclass
from zones import (
    QUEUE_ZONE_NAME,
    DWELL_ZONE_NAME,
    SHELF_ZONE_NAME,
    get_zone_for_point
)


@dataclass
class AnalyticsResult:
    """Standardized metrics payload generated by the analytics engine."""
    active_person_ids: set          # Currently detected person track IDs
    num_active_people: int          # Active people count in current frame
    total_unique_visitors: int      # Cumulative unique person IDs seen
    zone_occupancy: dict            # {zone_name: person_count}
    person_zones: dict              # {track_id: zone_name}
    queue_count: int                # People currently inside Checkout Zone
    is_queue_alert: bool            # True if queue_count >= queue_threshold
    current_dwells: dict            # {track_id: elapsed_seconds} for Store Zone
    avg_dwell: float                # Average dwell seconds for Store Zone occupants
    completed_dwells: dict          # {track_id: [final_dwell_seconds, ...]}


def _normalize_zone_name(z: str) -> str:
    """Normalizes zone name aliases (e.g. 'Store Zone' <-> 'Store Area')."""
    if z in ("Store Area", "Store Zone"):
        return "Store Area"
    if z in ("Checkout Area", "Checkout Zone"):
        return "Checkout Area"
    if z in ("Shelf Area", "Shelf Zone"):
        return "Shelf Area"
    return z


class StoreDwellTracker:
    """
    Dedicated Store Zone Dwell-Time Tracker.
    Maintains active dwell durations, departure logs, and timeout cleanup.
    Supports both direct ID updates and pipeline AnalyticsResult updates.
    """
    def __init__(self, zone_name=DWELL_ZONE_NAME, timeout_seconds=2.0):
        self.zone_name = zone_name
        self.timeout_seconds = timeout_seconds
        self.active_entries = {}
        self.last_seen = {}
        self.completed_dwells = {}

    def update(self, current_store_ids=None, all_active_ids=None, current_time=None, **kwargs):
        if current_time is None:
            current_time = time.time()

        # Handle positional or keyword argument invocation
        if isinstance(all_active_ids, dict):
            # Called from app.process_frame: current_store_ids=tracked_objects, all_active_ids=resolved_zones
            tracked_objects = current_store_ids
            resolved_zones = all_active_ids

            active_person_ids = set()
            store_person_ids = set()
            zone_occupancy = {name: 0 for name in resolved_zones}
            person_zones = {}

            for obj in tracked_objects:
                if not obj.is_person:
                    continue
                tid = obj.track_id
                if tid is not None:
                    active_person_ids.add(tid)
                    self.last_seen[tid] = current_time

                zone = get_zone_for_point(obj.center, resolved_zones)
                if zone:
                    zone_occupancy[zone] += 1
                    if tid is not None:
                        person_zones[tid] = zone
                        if _normalize_zone_name(zone) == _normalize_zone_name(self.zone_name):
                            store_person_ids.add(tid)

            # Mirror and combine aliases in zone_occupancy so both Area and Zone keys match
            for a_name, z_alias in [("Store Area", "Store Zone"), ("Shelf Area", "Shelf Zone"), ("Checkout Area", "Checkout Zone")]:
                combined = zone_occupancy.get(a_name, 0) + zone_occupancy.get(z_alias, 0)
                zone_occupancy[a_name] = combined
                zone_occupancy[z_alias] = combined

            current_dwells, avg_dwell = self._update_dwells(store_person_ids, active_person_ids, current_time)

            queue_cnt = zone_occupancy.get("Checkout Area", zone_occupancy.get("Checkout Zone", 0))
            return AnalyticsResult(
                active_person_ids=active_person_ids,
                num_active_people=len(active_person_ids),
                total_unique_visitors=len(active_person_ids),
                zone_occupancy=zone_occupancy,
                person_zones=person_zones,
                queue_count=queue_cnt,
                is_queue_alert=(queue_cnt >= 5),
                current_dwells=current_dwells,
                avg_dwell=avg_dwell,
                completed_dwells=self.completed_dwells
            )
        else:
            # Called from unit test: update(current_store_ids, all_active_ids)
            return self._update_dwells(current_store_ids or [], all_active_ids or [], current_time)

    def _update_dwells(self, current_store_ids, all_active_ids, current_time):
        for tid in all_active_ids:
            if tid is not None:
                self.last_seen[tid] = current_time

        current_dwells = {}
        for tid in current_store_ids:
            if tid is None:
                continue
            if tid not in self.active_entries:
                self.active_entries[tid] = current_time
            current_dwells[tid] = max(0.0, current_time - self.active_entries[tid])

        ids_to_finalize = []
        for tid in list(self.active_entries.keys()):
            if tid not in current_store_ids:
                if tid in all_active_ids:
                    ids_to_finalize.append((tid, current_time))
                else:
                    last_seen_t = self.last_seen.get(tid, self.active_entries[tid])
                    if (current_time - last_seen_t) >= self.timeout_seconds:
                        ids_to_finalize.append((tid, last_seen_t))

        for tid, exit_t in ids_to_finalize:
            entry_t = self.active_entries.pop(tid, None)
            if entry_t is not None:
                final_dwell = max(0.0, exit_t - entry_t)
                if tid not in self.completed_dwells:
                    self.completed_dwells[tid] = []
                self.completed_dwells[tid].append(round(final_dwell, 2))

        avg_dwell = sum(current_dwells.values()) / len(current_dwells) if current_dwells else 0.0
        return current_dwells, avg_dwell


class RetailAnalytics:
    """
    Computes business and operational analytics from tracked objects.
    Decoupled from OpenCV and visualization logic.
    """
    def __init__(
        self,
        queue_zone=QUEUE_ZONE_NAME,
        queue_threshold=5,
        dwell_zone=DWELL_ZONE_NAME,
        dwell_timeout=2.0
    ):
        self.queue_zone = queue_zone
        self.queue_threshold = queue_threshold
        self.dwell_zone = dwell_zone
        self.dwell_timeout = dwell_timeout

        # Cumulative unique visitors set
        self.unique_visitors = set()

        # Dwell tracking state
        self.active_dwell_entries = {}  # track_id -> entry_timestamp
        self.last_seen_times = {}       # track_id -> last_seen_timestamp
        self.completed_dwells = {}      # track_id -> list of final dwell durations

    def update(self, tracked_objects, resolved_zones, current_time=None):
        """
        Updates analytics given current tracked objects and resolved zone pixels.
        
        Args:
            tracked_objects: list of TrackedObject from tracker.py.
            resolved_zones: dict mapping zone_name -> (x1, y1, x2, y2).
            current_time: float timestamp (defaults to time.time()).
            
        Returns:
            AnalyticsResult dataclass.
        """
        if current_time is None:
            current_time = time.time()

        active_person_ids = set()
        store_person_ids = set()
        zone_occupancy = {name: 0 for name in resolved_zones}
        person_zones = {}

        # 1. Process tracked persons and zone containment
        for obj in tracked_objects:
            if not obj.is_person:
                continue

            tid = obj.track_id
            if tid is not None:
                active_person_ids.add(tid)
                self.unique_visitors.add(tid)
                self.last_seen_times[tid] = current_time

            # Check which zone contains the person's center point
            zone = get_zone_for_point(obj.center, resolved_zones)
            if zone:
                zone_occupancy[zone] += 1
                if tid is not None:
                    person_zones[tid] = zone
                    if _normalize_zone_name(zone) == _normalize_zone_name(self.dwell_zone):
                        store_person_ids.add(tid)

        # Mirror and combine aliases in zone_occupancy so both Area and Zone keys match
        for a_name, z_alias in [("Store Area", "Store Zone"), ("Shelf Area", "Shelf Zone"), ("Checkout Area", "Checkout Zone")]:
            combined = zone_occupancy.get(a_name, 0) + zone_occupancy.get(z_alias, 0)
            zone_occupancy[a_name] = combined
            zone_occupancy[z_alias] = combined

        # 2. Queue Analytics
        queue_count = zone_occupancy.get(self.queue_zone, zone_occupancy.get(_normalize_zone_name(self.queue_zone), 0))
        is_queue_alert = (queue_count >= self.queue_threshold)

        # 3. Dwell Time Tracking for Store Zone
        current_dwells = {}
        for tid in store_person_ids:
            if tid not in self.active_dwell_entries:
                self.active_dwell_entries[tid] = current_time
            current_dwells[tid] = max(0.0, current_time - self.active_dwell_entries[tid])

        # Check for departures from Store Zone (moved to other zone or disappeared)
        ids_to_finalize = []
        for tid in list(self.active_dwell_entries.keys()):
            if tid not in store_person_ids:
                if tid in active_person_ids:
                    # Still visible on camera, but moved outside Store Zone
                    ids_to_finalize.append((tid, current_time))
                else:
                    # Disappeared from camera: finalize after timeout using last seen timestamp
                    last_seen_t = self.last_seen_times.get(tid, self.active_dwell_entries[tid])
                    if (current_time - last_seen_t) >= self.dwell_timeout:
                        ids_to_finalize.append((tid, last_seen_t))

        for tid, exit_t in ids_to_finalize:
            entry_t = self.active_dwell_entries.pop(tid, None)
            if entry_t is not None:
                final_dwell = max(0.0, exit_t - entry_t)
                if tid not in self.completed_dwells:
                    self.completed_dwells[tid] = []
                self.completed_dwells[tid].append(round(final_dwell, 2))

        # Cleanup stale last seen entries
        stale_cutoff = current_time - (self.dwell_timeout * 3)
        stale_ids = [tid for tid, t in self.last_seen_times.items() if t < stale_cutoff and tid not in self.active_dwell_entries]
        for tid in stale_ids:
            self.last_seen_times.pop(tid, None)

        # Average Dwell Time across currently active Store Zone occupants
        avg_dwell = sum(current_dwells.values()) / len(current_dwells) if current_dwells else 0.0

        return AnalyticsResult(
            active_person_ids=active_person_ids,
            num_active_people=len(active_person_ids),
            total_unique_visitors=len(self.unique_visitors),
            zone_occupancy=zone_occupancy,
            person_zones=person_zones,
            queue_count=queue_count,
            is_queue_alert=is_queue_alert,
            current_dwells=current_dwells,
            avg_dwell=avg_dwell,
            completed_dwells=self.completed_dwells
        )

    def reset(self):
        """Resets all analytics state."""
        self.unique_visitors.clear()
        self.active_dwell_entries.clear()
        self.last_seen_times.clear()
        self.completed_dwells.clear()
